//#region src/utils/haptics.ts
function triggerHaptic(type = "light") {
	if (typeof window === "undefined" || typeof navigator === "undefined" || !navigator.vibrate) return;
	try {
		switch (type) {
			case "selection":
			case "light":
				navigator.vibrate(10);
				break;
			case "medium":
				navigator.vibrate(25);
				break;
			case "heavy":
				navigator.vibrate(50);
				break;
			case "success":
				navigator.vibrate([
					15,
					30,
					20
				]);
				break;
			case "warning":
				navigator.vibrate([
					30,
					50,
					30
				]);
				break;
			case "error":
				navigator.vibrate([
					50,
					50,
					50,
					50
				]);
				break;
			default: navigator.vibrate(15);
		}
	} catch {}
}
